CREATE TABLE IF NOT EXISTS project(id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL, project_id TEXT NOT NULL, settings TEXT NOT NULL, current_date TEXT NOT NULL, source_digest TEXT NOT NULL, imported_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cards(word TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS states(word TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(day TEXT PRIMARY KEY, session_id TEXT UNIQUE NOT NULL, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_log(log_id TEXT PRIMARY KEY, body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS operations(op_id TEXT PRIMARY KEY, payload_hash TEXT NOT NULL, response TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(day TEXT NOT NULL, group_id TEXT NOT NULL, signature TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', origin TEXT NOT NULL DEFAULT 'deepseek-api', content TEXT, content_hash TEXT, attempts INTEGER NOT NULL DEFAULT 0, lease_until INTEGER NOT NULL DEFAULT 0, lease_token TEXT, error TEXT, PRIMARY KEY(day,group_id));
CREATE TABLE IF NOT EXISTS audio(hash TEXT NOT NULL, chunk INTEGER NOT NULL, data BLOB NOT NULL, PRIMARY KEY(hash,chunk));
CREATE TABLE IF NOT EXISTS playback(session_id TEXT NOT NULL, group_id TEXT NOT NULL, revision INTEGER NOT NULL, body TEXT NOT NULL, PRIMARY KEY(session_id,group_id));
CREATE TABLE IF NOT EXISTS budget(day TEXT PRIMARY KEY, calls INTEGER NOT NULL DEFAULT 0, reserved_fen INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS generation_usage(id TEXT PRIMARY KEY, day TEXT NOT NULL, provider TEXT NOT NULL, usage TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS legacy_archive(path TEXT PRIMARY KEY, body TEXT NOT NULL, sha256 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audio_objects(hash TEXT PRIMARY KEY,size INTEGER NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS storage_budget(metric TEXT NOT NULL,period TEXT NOT NULL,amount INTEGER NOT NULL,PRIMARY KEY(metric,period));
